with recursive TagHierarchy TagsRecursive AS (
    select 
        t.Id, t.TagName, t.Count, t.IsModeratorOnly, array[t.TagName] as TagAncestors
    from Tags t
    where t.IsRequired = false
    union all
    select 
        tc.Id, tc.TagName, tc.Count, tc.IsModeratorOnly, th.TagAncestors || tc.TagName
    from Tags tc
    join StackOverflow.Posts p on p.Title like ('%<' || tc.TagName || ’>%’) and tc.IsRequired = false
    join TagsRecursive th ON array_position(th.TagAncestors, tc.TagName) IS NULL
),
